import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    void execute() {
        InputReader in = new InputReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int MOD = 998244353;
        int N = in.nextInt();
        int K = in.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < K; i++) {
            base[in.nextInt()] = 1;
        }
        int[] result = new int[]{1};
        int exp = N / 2;
        while (true) {
            if ((exp & 1) == 1) {
                result = convolve(result, base, MOD);
            }
            exp >>= 1;
            if (exp == 0) break;
            base = convolve(base, base, MOD);
        }
        long sum = 0;
        for (int val : result) {
            sum = (sum + (long)val * val) % MOD;
        }
        pw.println(sum);
        pw.close();
    }

    int[] convolve(int[] x, int[] y, int mod) {
        int len = x.length + y.length - 1;
        int size = 1;
        while (size < len) size <<= 1;

        double[] xr = new double[size];
        double[] xi = new double[size];
        for (int i = 0; i < x.length; i++) {
            long v = ((long)x[i] % mod + mod) % mod;
            xr[i] = v & 32767;
            xi[i] = v >>> 15;
        }

        transform(xr, xi, false);

        double[] yr = new double[size];
        double[] yi = new double[size];
        if (x == y) {
            System.arraycopy(xr, 0, yr, 0, size);
            System.arraycopy(xi, 0, yi, 0, size);
        } else {
            for (int i = 0; i < y.length; i++) {
                long v = ((long)y[i] % mod + mod) % mod;
                yr[i] = v & 32767;
                yi[i] = v >>> 15;
            }
            transform(yr, yi, false);
        }

        double[] resR = new double[size];
        double[] resI = new double[size];
        double factor = 0.25 / size;

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double ar = xr[i] + xr[j];
            double ai = xi[i] - xi[j];
            double ac = xi[i] + xi[j];
            double ad = xr[j] - xr[i];

            double br = yr[i] + yr[j];
            double bi = yi[i] - yi[j];
            double bc = yi[i] + yi[j];
            double bd = yr[j] - yr[i];

            resR[i] = (ar * br - ai * bi) * factor - (ac * bd + ad * bc) * factor;
            resI[i] = (ar * bi + ai * br) * factor + (ac * bc - ad * bd) * factor;
        }

        transform(resR, resI, true);

        int[] out = new int[len];
        for (int i = 0; i < len; i++) {
            long r = Math.round(resR[i]);
            long im = Math.round(resI[i]);
            long low = r % mod;
            long high = im % mod;
            out[i] = (int)((low + (high << 15)) % mod);
        }
        return out;
    }

    void transform(double[] re, double[] im, boolean inv) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            while (j >= bit) {
                j -= bit;
                bit >>= 1;
            }
            j += bit;
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int step = 2; step <= n; step <<= 1) {
            int half = step >> 1;
            double[] c = new double[half];
            double[] s = new double[half];
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / step * (inv ? -1 : 1);
                c[i] = Math.cos(angle);
                s[i] = Math.sin(angle);
            }

            for (int i = 0; i < n; i += step) {
                for (int k = 0; k < half; k++) {
                    double cr = re[i + k + half] * c[k] - im[i + k + half] * s[k];
                    double ci = re[i + k + half] * s[k] + im[i + k + half] * c[k];

                    double ur = re[i + k];
                    double ui = im[i + k];

                    re[i + k] = ur + cr;
                    im[i + k] = ui + ci;
                    re[i + k + half] = ur - cr;
                    im[i + k + half] = ui - ci;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (len == -1) throw new InputMismatchException();
            if (ptr >= len) {
                ptr = 0;
                try { len = stream.read(buffer); } catch (IOException e) { throw new InputMismatchException(); }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int val = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}
